source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny)); q.append((nx, ny))
            r0, r1 = min(x for x, y in cells), max(x for x, y in cells)
            c0, c1 = min(y for x, y in cells), max(y for x, y in cells)
            outside = set()
            q = deque()
            for x in range(r0, r1 + 1):
                for y in (c0, c1):
                    if grid[x][y] != color and (x, y) not in outside:
                        outside.add((x, y)); q.append((x, y))
            for y in range(c0, c1 + 1):
                for x in (r0, r1):
                    if grid[x][y] != color and (x, y) not in outside:
                        outside.add((x, y)); q.append((x, y))
            while q:
                x, y = q.popleft()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if r0 <= nx <= r1 and c0 <= ny <= c1 and grid[nx][ny] != color and (nx, ny) not in outside:
                        outside.add((nx, ny)); q.append((nx, ny))
            frame = any(grid[x][y] != color and (x, y) not in outside
                        for x in range(r0, r1 + 1) for y in range(c0, c1 + 1))
            objects.append((frame, cells, r0, r1))

    out = [[0] * w for _ in range(h)]
    placed = []
    # Frames pack upward; crosses pack downward, preserving their vertical order.
    for frame, direction in ((True, 1), (False, -1)):
        group = [obj for obj in objects if obj[0] == frame]
        group.sort(key=lambda obj: obj[2], reverse=(direction == -1))
        for _, cells, r0, r1 in group:
            height = r1 - r0 + 1
            target = 0 if direction == 1 else h - height
            def overlaps(start):
                return any((start + x - r0, y) in placed for x, y in cells)
            if direction == 1:
                while target + height <= h and overlaps(target):
                    target += 1
            else:
                while target >= 0 and overlaps(target):
                    target -= 1
            for x, y in cells:
                pos = (target + x - r0, y)
                out[pos[0]][pos[1]] = grid[x][y]
                placed.append(pos)
    return out
